import{_ as t,c as s,o as n,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"易原","description":"易原 - 易原","frontmatter":{"title":"易原","description":"易原 - 易原"},"headers":[],"relativePath":"zh/classics/yiyuan/001.md","filePath":"zh/classics/yiyuan/001.md"}'),l={name:"zh/classics/yiyuan/001.md"};function i(c,a,o,d,p,u){return n(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"易原",tabindex:"-1"},[r("易原 "),e("a",{class:"header-anchor",href:"#易原","aria-label":"Permalink to “易原”"},"​")],-1),e("p",null,"钦定四库全书经部一",-1),e("p",null,"易类提要",-1),e("p",null,"臣 等谨案：易原八卷，宋程大昌撰。大昌字泰之，休宁人。绍兴二十一年进士，历官权吏部尚书、龙图阁直学士。谥文简。大昌学术湛深，于诸经皆有论说。以易义自汉以来纠纷尤甚，因作是书以贯通之。苦思力索，四年而成。宋艺文志、文献通考皆著于录。陈振孙称其首论五十有五之数，参之图书，大衍为易之原，而卦变、揲法皆有图论，往往断以己见，出先儒之外。今考其所论分爻值日，乃京、焦卦气，其始于中孚，本用太初法，与夫子所谓「乾坤之策当期之日」者不合。复姤生卦，说始邵子，但乾坤生六子，说卦传有明文，不得先有六画之卦，后有三画之卦。郑康成用十日、十二辰、二十八宿以应大衍五十之数，本于乾凿度，与马融之增北辰，荀爽之增用九、用六，不过以意决比附，初无不易之理。张行成别立二十五数以推大衍，则是五十有五数之外，别有二十五数，更非孔子所曾言。其参互折衷，皆能根据大传，旁通交推，于易义实有所阐发，不徒文词之辨博己也。其书久无传本，惟程敏政新安文献志载有三篇，故朱彝尊经义考以为已佚。今散见于永乐大典中者，采掇得百有余篇，尚为完整，谨厘订编次，分为八卷。大昌禹贡图说尝刻入通志堂经解中，脱佚不完，已从永乐大典考辑补正。今是书复为裒缀成编，数百年诸儒未见之本，重得表章传世，庶俾大昌撰述之苦心借以不泯焉。乾隆四十九年十月恭校上。",-1),e("p",null,"总纂官 臣 纪昀、 臣 陆锡熊、 臣 孙士毅，总校官 臣 陆费墀。",-1)])])}const f=t(l,[["render",i]]);export{_ as __pageData,f as default};
